contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public {
        uint256 balBefore = address(c).balance;
        uint256 diffBefore = c.currentDifficulty(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.AdjustDifficulty(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 diffAfter = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;

        assert(reverted ? (diffAfter == diffBefore && balAfter == balBefore)
                        : (diffAfter == amount && balAfter == balBefore));
    }

    receive() external payable {}
}

